IF FirstScan THEN
    LOOP_2901A_TRIP := TRUE;
    LOOP_2901B_TRIP := TRUE;
    LOOP_2917_TRIP  := TRUE;
    SAFE_STATE      := TRUE;
    MCC_A_Out       := FALSE;
    MCC_B_Out       := FALSE;
    PSD_2917_Out    := FALSE;
    HY_2903A_Out    := 6554;
    HY_2903B_Out    := 6554;
    KV_2904_Out     := 6554;
    FirstScan       := FALSE;
    RETURN;
END_IF;

TI_2909_Scaled  := ((INT_TO_REAL(TI_2909_Raw)  - 6554.0) / (32767.0 - 6554.0)) * 100.0;
TT_2909_Scaled  := ((INT_TO_REAL(TT_2909_Raw)  - 6554.0) / (32767.0 - 6554.0)) * 100.0;
TT_2911_Scaled  := ((INT_TO_REAL(TT_2911_Raw)  - 6554.0) / (32767.0 - 6554.0)) * 100.0;
TT_2917_Scaled  := ((INT_TO_REAL(TT_2917_Raw)  - 6554.0) / (32767.0 - 6554.0)) * 100.0;
TI_2917_Scaled  := ((INT_TO_REAL(TI_2917_Raw)  - 6554.0) / (32767.0 - 6554.0)) * 100.0;
XI_2901A_Scaled := ((INT_TO_REAL(XI_2901A_Raw) - 6554.0) / (32767.0 - 6554.0)) * 100.0;
XI_2901B_Scaled := ((INT_TO_REAL(XI_2901B_Raw) - 6554.0) / (32767.0 - 6554.0)) * 100.0;

(* Local/Remote selector state — consumed in pump start logic *)
LocalRemote_A := HS_2901A1;
LocalRemote_B := HS_2901B1;

(* TI_2909 four-level alarms *)
IF TI_2909_Scaled >= TI_2909_HH_SP THEN
    TI_2909_HH_Latch.S1 := TRUE;
ELSIF TI_2909_Scaled <= (TI_2909_HH_SP - TI_2909_Deadband) THEN
    TI_2909_HH_Latch.S1 := FALSE;
END_IF;
TI_2909_HH_Latch.R := TI_2909_HH_Ack AND (TI_2909_Scaled < TI_2909_HH_SP);
TI_2909_HH_Latch(S1 := TI_2909_HH_Latch.S1, R := TI_2909_HH_Latch.R);

IF TI_2909_Scaled >= TI_2909_H_SP THEN
    TI_2909_H := TRUE;
ELSIF TI_2909_Scaled < (TI_2909_H_SP - TI_2909_Deadband) THEN
    TI_2909_H := FALSE;
END_IF;

IF TI_2909_Scaled <= TI_2909_L_SP THEN
    TI_2909_L := TRUE;
ELSIF TI_2909_Scaled > (TI_2909_L_SP + TI_2909_Deadband) THEN
    TI_2909_L := FALSE;
END_IF;

IF TI_2909_Scaled <= TI_2909_LL_SP THEN
    TI_2909_LL_Latch.S1 := TRUE;
ELSIF TI_2909_Scaled >= (TI_2909_LL_SP + TI_2909_Deadband) THEN
    TI_2909_LL_Latch.S1 := FALSE;
END_IF;
TI_2909_LL_Latch.R := TI_2909_LL_Ack AND (TI_2909_Scaled > TI_2909_LL_SP);
TI_2909_LL_Latch(S1 := TI_2909_LL_Latch.S1, R := TI_2909_LL_Latch.R);

(* TT_2909 four-level alarms *)
IF TT_2909_Scaled >= TT_2909_HH_SP THEN
    TT_2909_HH_Latch.S1 := TRUE;
ELSIF TT_2909_Scaled <= (TT_2909_HH_SP - TT_2909_Deadband) THEN
    TT_2909_HH_Latch.S1 := FALSE;
END_IF;
TT_2909_HH_Latch.R := TT_2909_HH_Ack AND (TT_2909_Scaled < TT_2909_HH_SP);
TT_2909_HH_Latch(S1 := TT_2909_HH_Latch.S1, R := TT_2909_HH_Latch.R);

IF TT_2909_Scaled >= TT_2909_H_SP THEN
    TT_2909_H := TRUE;
ELSIF TT_2909_Scaled < (TT_2909_H_SP - TT_2909_Deadband) THEN
    TT_2909_H := FALSE;
END_IF;

IF TT_2909_Scaled <= TT_2909_L_SP THEN
    TT_2909_L := TRUE;
ELSIF TT_2909_Scaled > (TT_2909_L_SP + TT_2909_Deadband) THEN
    TT_2909_L := FALSE;
END_IF;

IF TT_2909_Scaled <= TT_2909_LL_SP THEN
    TT_2909_LL_Latch.S1 := TRUE;
ELSIF TT_2909_Scaled >= (TT_2909_LL_SP + TT_2909_Deadband) THEN
    TT_2909_LL_Latch.S1 := FALSE;
END_IF;
TT_2909_LL_Latch.R := TT_2909_LL_Ack AND (TT_2909_Scaled > TT_2909_LL_SP);
TT_2909_LL_Latch(S1 := TT_2909_LL_Latch.S1, R := TT_2909_LL_Latch.R);

(* TT_2911 four-level alarms *)
IF TT_2911_Scaled >= TT_2911_HH_SP THEN
    TT_2911_HH_Latch.S1 := TRUE;
ELSIF TT_2911_Scaled <= (TT_2911_HH_SP - TT_2911_Deadband) THEN
    TT_2911_HH_Latch.S1 := FALSE;
END_IF;
TT_2911_HH_Latch.R := TT_2911_HH_Ack AND (TT_2911_Scaled < TT_2911_HH_SP);
TT_2911_HH_Latch(S1 := TT_2911_HH_Latch.S1, R := TT_2911_HH_Latch.R);

IF TT_2911_Scaled >= TT_2911_H_SP THEN
    TT_2911_H := TRUE;
ELSIF TT_2911_Scaled < (TT_2911_H_SP - TT_2911_Deadband) THEN
    TT_2911_H := FALSE;
END_IF;

IF TT_2911_Scaled <= TT_2911_L_SP THEN
    TT_2911_L := TRUE;
ELSIF TT_2911_Scaled > (TT_2911_L_SP + TT_2911_Deadband) THEN
    TT_2911_L := FALSE;
END_IF;

IF TT_2911_Scaled <= TT_2911_LL_SP THEN
    TT_2911_LL_Latch.S1 := TRUE;
ELSIF TT_2911_Scaled >= (TT_2911_LL_SP + TT_2911_Deadband) THEN
    TT_2911_LL_Latch.S1 := FALSE;
END_IF;
TT_2911_LL_Latch.R := TT_2911_LL_Ack AND (TT_2911_Scaled > TT_2911_LL_SP);
TT_2911_LL_Latch(S1 := TT_2911_LL_Latch.S1, R := TT_2911_LL_Latch.R);

(* TT_2917 four-level alarms *)
IF TT_2917_Scaled >= TT_2917_HH_SP THEN
    TT_2917_HH_Latch.S1 := TRUE;
ELSIF TT_2917_Scaled <= (TT_2917_HH_SP - TT_2917_Deadband) THEN
    TT_2917_HH_Latch.S1 := FALSE;
END_IF;
TT_2917_HH_Latch.R := TT_2917_HH_Ack AND (TT_2917_Scaled < TT_2917_HH_SP);
TT_2917_HH_Latch(S1 := TT_2917_HH_Latch.S1, R := TT_2917_HH_Latch.R);

IF TT_2917_Scaled >= TT_2917_H_SP THEN
    TT_2917_H := TRUE;
ELSIF TT_2917_Scaled < (TT_2917_H_SP - TT_2917_Deadband) THEN
    TT_2917_H := FALSE;
END_IF;

IF TT_2917_Scaled <= TT_2917_L_SP THEN
    TT_2917_L := TRUE;
ELSIF TT_2917_Scaled > (TT_2917_L_SP + TT_2917_Deadband) THEN
    TT_2917_L := FALSE;
END_IF;

IF TT_2917_Scaled <= TT_2917_LL_SP THEN
    TT_2917_LL_Latch.S1 := TRUE;
ELSIF TT_2917_Scaled >= (TT_2917_LL_SP + TT_2917_Deadband) THEN
    TT_2917_LL_Latch.S1 := FALSE;
END_IF;
TT_2917_LL_Latch.R := TT_2917_LL_Ack AND (TT_2917_Scaled > TT_2917_LL_SP);
TT_2917_LL_Latch(S1 := TT_2917_LL_Latch.S1, R := TT_2917_LL_Latch.R);

(* TI_2917 four-level alarms *)
IF TI_2917_Scaled >= TI_2917_HH_SP THEN
    TI_2917_HH_Latch.S1 := TRUE;
ELSIF TI_2917_Scaled <= (TI_2917_HH_SP - TI_2917_Deadband) THEN
    TI_2917_HH_Latch.S1 := FALSE;
END_IF;
TI_2917_HH_Latch.R := TI_2917_HH_Ack AND (TI_2917_Scaled < TI_2917_HH_SP);
TI_2917_HH_Latch(S1 := TI_2917_HH_Latch.S1, R := TI_2917_HH_Latch.R);

IF TI_2917_Scaled >= TI_2917_H_SP THEN
    TI_2917_H := TRUE;
ELSIF TI_2917_Scaled < (TI_2917_H_SP - TI_2917_Deadband) THEN
    TI_2917_H := FALSE;
END_IF;

IF TI_2917_Scaled <= TI_2917_L_SP THEN
    TI_2917_L := TRUE;
ELSIF TI_2917_Scaled > (TI_2917_L_SP + TI_2917_Deadband) THEN
    TI_2917_L := FALSE;
END_IF;

IF TI_2917_Scaled <= TI_2917_LL_SP THEN
    TI_2917_LL_Latch.S1 := TRUE;
ELSIF TI_2917_Scaled >= (TI_2917_LL_SP + TI_2917_Deadband) THEN
    TI_2917_LL_Latch.S1 := FALSE;
END_IF;
TI_2917_LL_Latch.R := TI_2917_LL_Ack AND (TI_2917_Scaled > TI_2917_LL_SP);
TI_2917_LL_Latch(S1 := TI_2917_LL_Latch.S1, R := TI_2917_LL_Latch.R);

(* XI_2901A four-level alarms *)
IF XI_2901A_Scaled >= XI_2901A_HH_SP THEN
    XI_2901A_HH_Latch.S1 := TRUE;
ELSIF XI_2901A_Scaled <= (XI_2901A_HH_SP - XI_2901A_Deadband) THEN
    XI_2901A_HH_Latch.S1 := FALSE;
END_IF;
XI_2901A_HH_Latch.R := XI_2901A_HH_Ack AND (XI_2901A_Scaled < XI_2901A_HH_SP);
XI_2901A_HH_Latch(S1 := XI_2901A_HH_Latch.S1, R := XI_2901A_HH_Latch.R);

IF XI_2901A_Scaled >= XI_2901A_H_SP THEN
    XI_2901A_H := TRUE;
ELSIF XI_2901A_Scaled < (XI_2901A_H_SP - XI_2901A_Deadband) THEN
    XI_2901A_H := FALSE;
END_IF;

IF XI_2901A_Scaled <= XI_2901A_L_SP THEN
    XI_2901A_L := TRUE;
ELSIF XI_2901A_Scaled > (XI_2901A_L_SP + XI_2901A_Deadband) THEN
    XI_2901A_L := FALSE;
END_IF;

IF XI_2901A_Scaled <= XI_2901A_LL_SP THEN
    XI_2901A_LL_Latch.S1 := TRUE;
ELSIF XI_2901A_Scaled >= (XI_2901A_LL_SP + XI_2901A_Deadband) THEN
    XI_2901A_LL_Latch.S1 := FALSE;
END_IF;
XI_2901A_LL_Latch.R := XI_2901A_LL_Ack AND (XI_2901A_Scaled > XI_2901A_LL_SP);
XI_2901A_LL_Latch(S1 := XI_2901A_LL_Latch.S1, R := XI_2901A_LL_Latch.R);

(* XI_2901B four-level alarms *)
IF XI_2901B_Scaled >= XI_2901B_HH_SP THEN
    XI_2901B_HH_Latch.S1 := TRUE;
ELSIF XI_2901B_Scaled <= (XI_2901B_HH_SP - XI_2901B_Deadband) THEN
    XI_2901B_HH_Latch.S1 := FALSE;
END_IF;
XI_2901B_HH_Latch.R := XI_2901B_HH_Ack AND (XI_2901B_Scaled < XI_2901B_HH_SP);
XI_2901B_HH_Latch(S1 := XI_2901B_HH_Latch.S1, R := XI_2901B_HH_Latch.R);

IF XI_2901B_Scaled >= XI_2901B_H_SP THEN
    XI_2901B_H := TRUE;
ELSIF XI_2901B_Scaled < (XI_2901B_H_SP - XI_2901B_Deadband) THEN
    XI_2901B_H := FALSE;
END_IF;

IF XI_2901B_Scaled <= XI_2901B_L_SP THEN
    XI_2901B_L := TRUE;
ELSIF XI_2901B_Scaled > (XI_2901B_L_SP + XI_2901B_Deadband) THEN
    XI_2901B_L := FALSE;
END_IF;

IF XI_2901B_Scaled <= XI_2901B_LL_SP THEN
    XI_2901B_LL_Latch.S1 := TRUE;
ELSIF XI_2901B_Scaled >= (XI_2901B_LL_SP + XI_2901B_Deadband) THEN
    XI_2901B_LL_Latch.S1 := FALSE;
END_IF;
XI_2901B_LL_Latch.R := XI_2901B_LL_Ack AND (XI_2901B_Scaled > XI_2901B_LL_SP);
XI_2901B_LL_Latch(S1 := XI_2901B_LL_Latch.S1, R := XI_2901B_LL_Latch.R);

VSHH_2901A_HH := VSHH_2901A;
VSHH_2901A_LL := FALSE;
VSHH_2901B_HH := VSHH_2901B;
VSHH_2901B_LL := FALSE;
TT_2917_HH    := TT_2917_HH_Latch.Q1;
TT_2917_LL    := TT_2917_LL_Latch.Q1;

(* Loop 2901A trip latch *)
IF VSHH_2901A_HH OR VSHH_2901A_LL OR HS_ESTOP_A_2901A THEN
    LOOP_2901A_TRIP := TRUE;
ELSIF LOOP_2901A_TRIP AND MANUAL_RESET
      AND NOT VSHH_2901A_HH AND NOT VSHH_2901A_LL AND NOT HS_ESTOP_A_2901A THEN
    LOOP_2901A_TRIP := FALSE;
END_IF;

(* Loop 2901B trip latch *)
IF VSHH_2901B_HH OR VSHH_2901B_LL OR HS_ESTOP_B_2901B THEN
    LOOP_2901B_TRIP := TRUE;
ELSIF LOOP_2901B_TRIP AND MANUAL_RESET
      AND NOT VSHH_2901B_HH AND NOT VSHH_2901B_LL AND NOT HS_ESTOP_B_2901B THEN
    LOOP_2901B_TRIP := FALSE;
END_IF;

(* Loop 2917 trip latch — temperature high/low or pressure switch open *)
IF TT_2917_HH OR TT_2917_LL OR NOT PSD_2917 THEN
    LOOP_2917_TRIP := TRUE;
ELSIF LOOP_2917_TRIP AND MANUAL_RESET
      AND NOT TT_2917_HH AND NOT TT_2917_LL AND PSD_2917 THEN
    LOOP_2917_TRIP := FALSE;
END_IF;

SAFE_STATE := ESTOP
              OR ESD_3200
              OR LOOP_2901A_TRIP
              OR LOOP_2901B_TRIP
              OR LOOP_2917_TRIP;

(* Pump A start/stop latch — local or remote start commands, inhibited in safe state *)
PumpA_StartStop_Latch.S1 := (HS_START_STOP_A_2901A OR (LocalRemote_A AND HS_2901A) OR HS_2901A2)
                             AND NOT SAFE_STATE;
PumpA_StartStop_Latch.R  := NOT HS_START_STOP_A_2901A AND NOT HS_2901A AND NOT HS_2901A2;
PumpA_StartStop_Latch(S1 := PumpA_StartStop_Latch.S1, R := PumpA_StartStop_Latch.R);
PumpA_Run := PumpA_StartStop_Latch.Q1;

(* Pump B start/stop latch *)
PumpB_StartStop_Latch.S1 := (HS_START_STOP_B_2901B OR (LocalRemote_B AND HS_2901B) OR HS_2901B2)
                             AND NOT SAFE_STATE;
PumpB_StartStop_Latch.R  := NOT HS_START_STOP_B_2901B AND NOT HS_2901B AND NOT HS_2901B2;
PumpB_StartStop_Latch(S1 := PumpB_StartStop_Latch.S1, R := PumpB_StartStop_Latch.R);
PumpB_Run := PumpB_StartStop_Latch.Q1;

(* TT_2911 PI temperature controller — drives HY_2903A, HY_2903B, KV_2904 *)
IF NOT SAFE_STATE THEN
    TT_2911_Error    := TT_2911_SP - TT_2911_Scaled;
    TT_2911_Integral := TT_2911_Integral + (TT_2911_Ki * TT_2911_Error);
    IF TT_2911_Integral > 100.0 THEN
        TT_2911_Integral := 100.0;
    ELSIF TT_2911_Integral < 0.0 THEN
        TT_2911_Integral := 0.0;
    END_IF;
    TT_2911_Output_Pct := (TT_2911_Kp * TT_2911_Error) + TT_2911_Integral;
    IF TT_2911_Output_Pct > 100.0 THEN
        TT_2911_Output_Pct := 100.0;
    ELSIF TT_2911_Output_Pct < 0.0 THEN
        TT_2911_Output_Pct := 0.0;
    END_IF;
    HY_2903A_Pct := TT_2911_Output_Pct;
    HY_2903B_Pct := TT_2911_Output_Pct;
    KV_2904_Pct  := TT_2911_Output_Pct;
    HY_2903A_Out := REAL_TO_INT(6554.0 + (HY_2903A_Pct / 100.0) * (32767.0 - 6554.0));
    HY_2903B_Out := REAL_TO_INT(6554.0 + (HY_2903B_Pct / 100.0) * (32767.0 - 6554.0));
    KV_2904_Out  := REAL_TO_INT(6554.0 + (KV_2904_Pct  / 100.0) * (32767.0 - 6554.0));
    MCC_A_Out    := PumpA_Run;
    MCC_B_Out    := PumpB_Run;
    PSD_2917_Out := PSD_2917;
ELSE
    HY_2903A_Out     := 6554;
    HY_2903B_Out     := 6554;
    KV_2904_Out      := 6554;
    MCC_A_Out        := FALSE;
    MCC_B_Out        := FALSE;
    PSD_2917_Out     := FALSE;
    TT_2911_Integral := 0.0;
END_IF;

System_Alarm :=
    TI_2909_HH_Latch.Q1  OR TI_2909_LL_Latch.Q1  OR TI_2909_H  OR TI_2909_L  OR
    TT_2909_HH_Latch.Q1  OR TT_2909_LL_Latch.Q1  OR TT_2909_H  OR TT_2909_L  OR
    TT_2911_HH_Latch.Q1  OR TT_2911_LL_Latch.Q1  OR TT_2911_H  OR TT_2911_L  OR
    TT_2917_HH_Latch.Q1  OR TT_2917_LL_Latch.Q1  OR TT_2917_H  OR TT_2917_L  OR
    TI_2917_HH_Latch.Q1  OR TI_2917_LL_Latch.Q1  OR TI_2917_H  OR TI_2917_L  OR
    XI_2901A_HH_Latch.Q1 OR XI_2901A_LL_Latch.Q1 OR XI_2901A_H OR XI_2901A_L OR
    XI_2901B_HH_Latch.Q1 OR XI_2901B_LL_Latch.Q1 OR XI_2901B_H OR XI_2901B_L OR
    LOOP_2901A_TRIP OR LOOP_2901B_TRIP OR LOOP_2917_TRIP OR SAFE_STATE;
